SELECT m.member_id AS memberId, m.login_id AS loginId, m.name AS name, m.email AS email, m.phone AS phone, m.status AS status, m.role AS role, m.grade_id AS gradeId, g.grade_name AS gradeName, m.last_login_at AS lastLoginAt, m.created_at AS createdAt FROM member m LEFT JOIN grade g ON m.grade_id = g.grade_id
AND m.status = #{status}
AND m.grade_id = #{gradeId}
AND ( m.login_id LIKE CONCAT('%', #{kw}, '%') OR m.name LIKE CONCAT('%', #{kw}, '%') OR m.email LIKE CONCAT('%', #{kw}, '%') OR m.phone LIKE CONCAT('%', #{kw}, '%') )
ORDER BY m.member_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM member m


		AND m.status = #{status}



		AND m.grade_id = #{gradeId}



		AND (
		m.login_id LIKE CONCAT('%', #{keyword}, '%')
		OR m.name LIKE CONCAT('%', #{keyword}, '%')
		OR m.email LIKE CONCAT('%', #{keyword}, '%')
		OR m.phone LIKE CONCAT('%', #{keyword}, '%')
		)
